1	import { Show, type Accessor } from "solid-js";
2	import type { I18nContextType } from "../../i18n";
3	import { hotkeyDisplayName } from "../../lib/hotkeyUtils";
4	import type { Settings } from "../../lib/settingsStore";
5	
6	interface HotkeySettingsProps {
7		t: I18nContextType[0];
8		settings: Accessor<Settings>;
9		isRecordingHotkey: boolean;
10		pendingHotkey: string | null;
11		hotkeyError: string | null;
12		onToggleHotkeyRecording: () => void;
13		isRecordingHoldToSpeakHotkey: boolean;
14		pendingHoldToSpeakHotkey: string | null;
15		holdToSpeakHotkeyError: string | null;
16		onToggleHoldToSpeakHotkeyRecording: () => void;
17	}
18	
19	export default function HotkeySettings(props: HotkeySettingsProps) {
20		return (
21			<div class="space-y-6">
22				<div>
23					<div class="font-mono text-txt-muted text-xs uppercase tracking-wider block mb-3">
24						HANDS_FREE_TRIGGER
25					</div>
26					<div class="flex items-center gap-3">
27						<div
28							class={`flex-1 px-4 py-3 border font-mono text-center text-sm ${
29								props.isRecordingHotkey
30									? "border-ac bg-ac-bg text-ac"
31									: "border-border-strong bg-th-surface text-txt-primary"
32							}`}
33						>
34							{props.isRecordingHotkey
35								? props.pendingHotkey || "_ WAITING FOR INPUT _"
36								: hotkeyDisplayName(props.settings().hotkey)}
37						</div>
38						<button
39							type="button"
40							onClick={props.onToggleHotkeyRecording}
41							disabled={
42								props.holdToSpeakHotkeyError !== null ||
43								(props.isRecordingHoldToSpeakHotkey && !props.isRecordingHotkey)
44							}
45							class={`px-4 py-3 font-mono text-xs uppercase tracking-wider transition-colors disabled:opacity-50 ${
46								props.isRecordingHotkey
47									? "bg-border text-txt-secondary hover:bg-border-strong"
48									: "bg-ac text-ac-on hover:bg-ac-hover"
49							}`}
50						>
51							{props.isRecordingHotkey ? "[CANCEL]" : "[CHANGE]"}
52						</button>
53					</div>
54					<Show when={props.hotkeyError}>
55						<div class="font-mono text-xs text-red-500">{props.hotkeyError}</div>
56					</Show>
57					<p class="mt-3 font-mono text-xs text-txt-faint">{props.t("settings.hotkeyDescription")}</p>
58				</div>
59				<div>
60					<div class="font-mono text-txt-muted text-xs uppercase tracking-wider block mb-3">
61						HOLD_TO_SPEAK_TRIGGER
62					</div>
63					<div class="flex items-center gap-3">
64						<div
65							class={`flex-1 px-4 py-3 border font-mono text-center text-sm ${
66								props.isRecordingHoldToSpeakHotkey
67									? "border-ac bg-ac-bg text-ac"
68									: "border-border-strong bg-th-surface text-txt-primary"
69							}`}
70						>
71							{props.isRecordingHoldToSpeakHotkey
72								? props.pendingHoldToSpeakHotkey || "_ WAITING FOR INPUT _"
73								: hotkeyDisplayName(props.settings().holdToSpeakHotkey)}
74						</div>
75						<button
76							type="button"
77							onClick={props.onToggleHoldToSpeakHotkeyRecording}
78							disabled={
79								props.hotkeyError !== null ||
80								(props.isRecordingHotkey && !props.isRecordingHoldToSpeakHotkey)
81							}
82							class={`px-4 py-3 font-mono text-xs uppercase tracking-wider transition-colors disabled:opacity-50 ${
83								props.isRecordingHoldToSpeakHotkey
84									? "bg-border text-txt-secondary hover:bg-border-strong"
85									: "bg-ac text-ac-on hover:bg-ac-hover"
86							}`}
87						>
88							{props.isRecordingHoldToSpeakHotkey ? "[CANCEL]" : "[CHANGE]"}
89						</button>
90					</div>
91					<Show when={props.holdToSpeakHotkeyError}>
92						<div class="font-mono text-xs text-red-500">{props.holdToSpeakHotkeyError}</div>
93					</Show>
94					<p class="mt-3 font-mono text-xs text-txt-faint">
95						{props.t("settings.holdToSpeakHotkeyDescription")}
96					</p>
97				</div>
98			</div>
99		);
100	}
