67	export async function loadSettings(): Promise<Settings> {
68		const store = await getStore();
69		const theme = await store.get<Theme>("theme");
70		const hotkey = await store.get<string>("hotkey");
71		const holdToSpeakHotkey = await store.get<string>("holdToSpeakHotkey");
72		const selectedMicrophoneId = await store.get<string | null>("selectedMicrophoneId");
73		const language = await store.get<Locale>("language");
74		const muteMediaWhileRecording = await store.get<boolean>("muteMediaWhileRecording");
75		const storedDefaultStyle = await store.get<AppStyle>("defaultStyle");
76		const defaultStyle =
77			storedDefaultStyle && STYLE_LIST.includes(storedDefaultStyle)
78				? storedDefaultStyle
79				: DEFAULT_SETTINGS.defaultStyle;
80		const onboardingComplete = await store.get<boolean>("onboardingComplete");
81		const onboardingStep = await store.get<number>("onboardingStep");
82		const onboardingVersion = await store.get<number>("onboardingVersion");
83		const normalizedOnboardingStep = normalizeOnboardingStep(
84			onboardingStep ?? DEFAULT_SETTINGS.onboardingStep,
85			onboardingComplete ?? DEFAULT_SETTINGS.onboardingComplete,
86			onboardingVersion ?? 1
87		);
88	
89		if (normalizedOnboardingStep !== (onboardingStep ?? DEFAULT_SETTINGS.onboardingStep)) {
90			await store.set("onboardingStep", normalizedOnboardingStep);
91		}
92		if ((onboardingVersion ?? 1) !== CURRENT_ONBOARDING_VERSION) {
93			await store.set("onboardingVersion", CURRENT_ONBOARDING_VERSION);
94		}
95	
96		return {
97			theme: theme ?? DEFAULT_SETTINGS.theme,
98			hotkey: hotkey ?? DEFAULT_SETTINGS.hotkey,
99			holdToSpeakHotkey: holdToSpeakHotkey ?? DEFAULT_SETTINGS.holdToSpeakHotkey,
100			selectedMicrophoneId: selectedMicrophoneId ?? DEFAULT_SETTINGS.selectedMicrophoneId,
101			language: language ?? DEFAULT_SETTINGS.language,
102			muteMediaWhileRecording: muteMediaWhileRecording ?? DEFAULT_SETTINGS.muteMediaWhileRecording,
103			defaultStyle,
104			onboardingComplete: onboardingComplete ?? DEFAULT_SETTINGS.onboardingComplete,
105			onboardingStep: normalizedOnboardingStep,
106		};
107	}
