248			try: async () => {
249				const store = await getStore();
250				await store.set("onboardingComplete", true);
251				await store.set("onboardingStep", 1);
252				await store.save();
253				await emit("settings-changed");
254			},
255			catch: (cause) => storageError("persist onboarding completion", cause),
256		});
257		if (Result.isError(result)) {
258			console.error("Failed to persist onboarding completion:", result.error);
259		}
260	}
