32	function waitForTauriIPC(): Promise<void> {
33		if ((window as TauriWindow).__TAURI_INTERNALS__) return Promise.resolve();
34	
35		return new Promise((resolve, reject) => {
36			const timeout = setTimeout(() => {
37				clearInterval(interval);
38				reject(new Error("Tauri IPC bridge not ready after 5s"));
39			}, 5000);
40	
41			const interval = setInterval(() => {
42				if ((window as TauriWindow).__TAURI_INTERNALS__) {
43					clearInterval(interval);
44					clearTimeout(timeout);
45					resolve();
46				}
47			}, 50);
48		});
49	}
