1	use std::collections::BTreeSet;
2	use std::ptr::NonNull;
3	use std::sync::atomic::{AtomicBool, Ordering};
4	use std::sync::{Mutex, OnceLock};
5	
6	use block2::RcBlock;
7	use objc2_app_kit::{NSEvent, NSEventMask, NSEventModifierFlags, NSEventType};
8	use serde::Serialize;
9	use tauri::Emitter;
10	
11	static APP_HANDLE: OnceLock<tauri::AppHandle> = OnceLock::new();
12	static PRESSED_KEYS: OnceLock<Mutex<BTreeSet<SystemKey>>> = OnceLock::new();
13	static WATCHER_RUNNING: AtomicBool = AtomicBool::new(false);
14	
15	// Virtual key codes for the modifier keys we track. These are stable,
16	// hardware-independent key codes shared by Core Graphics and AppKit.
17	const KEYCODE_FN: u16 = 0x3F;
18	const KEYCODE_LEFT_CONTROL: u16 = 0x3B;
19	const KEYCODE_RIGHT_CONTROL: u16 = 0x3E;
20	const KEYCODE_LEFT_OPTION: u16 = 0x3A;
21	const KEYCODE_RIGHT_OPTION: u16 = 0x3D;
22	const KEYCODE_LEFT_COMMAND: u16 = 0x37;
23	const KEYCODE_RIGHT_COMMAND: u16 = 0x36;
24	
25	#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd, Serialize)]
26	#[serde(rename_all = "camelCase")]
27	enum SystemKey {
28	    Fn,
29	    LeftControl,
30	    RightControl,
31	    LeftOption,
32	    RightOption,
33	    LeftCommand,
34	    RightCommand,
35	}
36	
37	#[derive(Clone, Debug, Serialize)]
38	#[serde(rename_all = "camelCase")]
39	struct SystemKeyPressedPayload {
40	    key: SystemKey,
41	    pressed_keys: Vec<SystemKey>,
42	}
43	
44	#[derive(Clone, Debug, Serialize)]
45	#[serde(rename_all = "camelCase")]
46	struct SystemKeyReleasedPayload {
47	    key: SystemKey,
48	    pressed_keys: Vec<SystemKey>,
49	}
50	
51	#[derive(Clone, Debug, Serialize)]
52	#[serde(rename_all = "camelCase")]
53	struct KeyboardKeyPressedPayload {
54	    key_code: i64,
55	}
56	
57	fn pressed_keys() -> &'static Mutex<BTreeSet<SystemKey>> {
58	    PRESSED_KEYS.get_or_init(|| Mutex::new(BTreeSet::new()))
59	}
60	
61	fn key_from_keycode(keycode: u16) -> Option<SystemKey> {
62	    match keycode {
63	        KEYCODE_FN => Some(SystemKey::Fn),
64	        KEYCODE_LEFT_CONTROL => Some(SystemKey::LeftControl),
65	        KEYCODE_RIGHT_CONTROL => Some(SystemKey::RightControl),
66	        KEYCODE_LEFT_OPTION => Some(SystemKey::LeftOption),
67	        KEYCODE_RIGHT_OPTION => Some(SystemKey::RightOption),
68	        KEYCODE_LEFT_COMMAND => Some(SystemKey::LeftCommand),
69	        KEYCODE_RIGHT_COMMAND => Some(SystemKey::RightCommand),
70	        _ => None,
71	    }
72	}
73	
74	fn key_is_down_in_flags(key: SystemKey, flags: NSEventModifierFlags) -> bool {
75	    match key {
76	        SystemKey::Fn => flags.contains(NSEventModifierFlags::Function),
77	        SystemKey::LeftControl | SystemKey::RightControl => {
78	            flags.contains(NSEventModifierFlags::Control)
79	        }
80	        SystemKey::LeftOption | SystemKey::RightOption => {
81	            flags.contains(NSEventModifierFlags::Option)
82	        }
83	        SystemKey::LeftCommand | SystemKey::RightCommand => {
84	            flags.contains(NSEventModifierFlags::Command)
85	        }
86	    }
87	}
88	
89	fn emit_system_key_event(event: &NSEvent) {
90	    let Some(app_handle) = APP_HANDLE.get() else {
91	        return;
92	    };
93	
94	    let Some(key) = key_from_keycode(event.keyCode()) else {
95	        return;
96	    };
97	
98	    let flags = event.modifierFlags();
99	    let is_down = key_is_down_in_flags(key, flags);
100	    let mut pressed = pressed_keys()
101	        .lock()
102	        .expect("system key pressed state mutex poisoned");
103	
104	    if is_down {
105	        let was_new_key = pressed.insert(key);
106	
107	        if was_new_key {
108	            let _ = app_handle.emit(
109	                "system-key-pressed",
110	                SystemKeyPressedPayload {
111	                    key,
112	                    pressed_keys: pressed.iter().copied().collect(),
113	                },
114	            );
115	        }
116	
117	        return;
118	    }
119	
120	    if pressed.remove(&key) {
121	        let pressed_keys = pressed.iter().copied().collect::<Vec<_>>();
122	        let _ = app_handle.emit(
123	            "system-key-released",
124	            SystemKeyReleasedPayload { key, pressed_keys },
125	        );
126	
127	        if pressed.is_empty() {
128	            let _ = app_handle.emit("system-keys-released", ());
129	        }
130	    }
131	}
132	
133	fn emit_keyboard_key_pressed(event: &NSEvent) {
134	    let Some(app_handle) = APP_HANDLE.get() else {
135	        return;
136	    };
137	
138	    if event.isARepeat() {
139	        return;
140	    }
141	
142	    let key_code = event.keyCode() as i64;
143	    let _ = app_handle.emit(
144	        "keyboard-key-pressed",
145	        KeyboardKeyPressedPayload { key_code },
146	    );
147	}
148	
149	fn handle_event(event: &NSEvent) {
150	    match event.r#type() {
151	        NSEventType::FlagsChanged => emit_system_key_event(event),
152	        NSEventType::KeyDown => emit_keyboard_key_pressed(event),
153	        _ => {}
154	    }
155	}
156	
157	pub fn setup(app_handle: &tauri::AppHandle) {
158	    APP_HANDLE.set(app_handle.clone()).ok();
159	
160	    if WATCHER_RUNNING.swap(true, Ordering::SeqCst) {
161	        return;
162	    }
163	
164	    // NSEvent monitors must be installed on the main thread, where the
165	    // application run loop dispatches them. Observing `FlagsChanged` (for
166	    // modifier-only hotkeys) via NSEvent — rather than a Core Graphics event
167	    // tap — means we no longer require the macOS Input Monitoring permission.
168	    let scheduled = app_handle.run_on_main_thread(|| {
169	        let mask = NSEventMask::FlagsChanged | NSEventMask::KeyDown;
170	
171	        // Events delivered to *other* applications — the usual case while
172	        // dictating into another app.
173	        let global_block = RcBlock::new(|event: NonNull<NSEvent>| {
174	            handle_event(unsafe { event.as_ref() });
175	        });
176	        let global_monitor =
177	            NSEvent::addGlobalMonitorForEventsMatchingMask_handler(mask, &global_block);
178	
179	        // Events delivered to our own window — e.g. while recording a hotkey
180	        // in Settings, or for keys AppKit doesn't surface to the DOM (Fn).
181	        // The handler observes only and passes every event through unchanged.
182	        let local_block = RcBlock::new(|event: NonNull<NSEvent>| -> *mut NSEvent {
183	            handle_event(unsafe { event.as_ref() });
184	            event.as_ptr()
185	        });
186	        // SAFETY: the block returns the event pointer it was given, so the
187	        // event is always forwarded unchanged.
188	        let local_monitor =
189	            unsafe { NSEvent::addLocalMonitorForEventsMatchingMask_handler(mask, &local_block) };
190	
191	        // The monitors live for the entire lifetime of the app; leak the
192	        // returned tokens so the monitors are never torn down.
193	        std::mem::forget(global_monitor);
194	        std::mem::forget(local_monitor);
195	    });
196	
197	    if scheduled.is_err() {
198	        WATCHER_RUNNING.store(false, Ordering::SeqCst);
199	    }
200	}
